3	67	SELECT\n    DATE_TRUNC('month', soh.orderdate) AS sales_month,\n    EXTRACT(YEAR FROM soh.orderdate) AS sales_year,\n    EXTRACT(MONTH FROM soh.orderdate) AS sales_month_num,\n    COUNT(soh.salesorderid) AS total_orders,\n    SUM(soh.totaldue) AS total_revenue,\n    SUM(soh.subtotal) AS total_subtotal,\n    SUM(soh.taxamt) AS total_tax,\n    SUM(soh.freight) AS total_freight,\n    LAG(SUM(soh.totaldue), 12) OVER (ORDER BY DATE_TRUNC('month', soh.orderdate)) AS previous_year_revenue,\n    ROUND(\n        ((SUM(soh.totaldue) - LAG(SUM(soh.totaldue), 12) OVER (ORDER BY DATE_TRUNC('month', soh.orderdate))) / \n        NULLIF(LAG(SUM(soh.totaldue), 12) OVER (ORDER BY DATE_TRUNC('month', soh.orderdate)), 0)) * 100,\n        2\n    ) AS yoy_growth_pct\nFROM sales.salesorderheader soh\nWHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\nGROUP BY DATE_TRUNC('month', soh.orderdate), EXTRACT(YEAR FROM soh.orderdate), EXTRACT(MONTH FROM soh.orderdate)\nORDER BY sales_month\nLIMIT 1000\n---\nSELECT\n    DATE_TRUNC('month', soh.orderdate) AS sales_month,\n    EXTRACT(YEAR FROM soh.orderdate) AS sales_year,\n    st.territoryid,\n    st.name AS territory_name,\n    st.group AS territory_group,\n    COUNT(soh.salesorderid) AS total_orders,\n    SUM(soh.totaldue) AS total_revenue,\n    AVG(soh.totaldue) AS avg_order_value,\n    LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.territoryid ORDER BY DATE_TRUNC('month', soh.orderdate)) AS previous_year_revenue,\n    ROUND(\n        ((SUM(soh.totaldue) - LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.territoryid ORDER BY DATE_TRUNC('month', soh.orderdate))) / \n        NULLIF(LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.territoryid ORDER BY DATE_TRUNC('month', soh.orderdate)), 0)) * 100,\n        2\n    ) AS yoy_growth_pct\nFROM sales.salesorderheader soh\nINNER JOIN sales.salesterritory st ON soh.territoryid = st.territoryid\nWHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\nGROUP BY DATE_TRUNC('month', soh.orderdate), EXTRACT(YEAR FROM soh.orderdate), st.territoryid, st.name, st.group\nORDER BY sales_month, st.territoryid\nLIMIT 1000\n---\nSELECT\n    DATE_TRUNC('month', soh.orderdate) AS sales_month,\n    EXTRACT(YEAR FROM soh.orderdate) AS sales_year,\n    EXTRACT(MONTH FROM soh.orderdate) AS sales_month_num,\n    sod.productid,\n    p.name AS product_name,\n    p.productnumber,\n    ps.name AS product_subcategory,\n    pc.name AS product_category,\n    SUM(sod.orderqty) AS total_quantity_sold,\n    SUM(sod.linetotal) AS total_revenue,\n    AVG(sod.unitprice) AS avg_unit_price,\n    LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY sod.productid ORDER BY DATE_TRUNC('month', soh.orderdate)) AS previous_year_revenue,\n    ROUND(\n        ((SUM(sod.linetotal) - LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY sod.productid ORDER BY DATE_TRUNC('month', soh.orderdate))) / \n        NULLIF(LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY sod.productid ORDER BY DATE_TRUNC('month', soh.orderdate)), 0)) * 100,\n        2\n    ) AS yoy_growth_pct\nFROM sales.salesorderheader soh\nINNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid\nINNER JOIN production.product p ON sod.productid = p.productid\nLEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid\nLEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid\nWHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\nGROUP BY DATE_TRUNC('month', soh.orderdate), EXTRACT(YEAR FROM soh.orderdate), EXTRACT(MONTH FROM soh.orderdate), sod.productid, p.name, p.productnumber, ps.name, pc.name\nORDER BY sales_month, total_revenue DESC\nLIMIT 1000	[]	{"data": {"labels": [], "datasets": [{"data": [], "label": "Año Actual", "backgroundColor": ["#4f46e5"]}, {"data": [], "label": "Año Anterior", "backgroundColor": ["#06b6d4"]}]}, "type": "bar", "title": "Ventas por Mes de los Últimos 3 Años", "columns": [{"key": "mes", "type": "string", "label": "Mes"}, {"key": 