4	73	WITH monthly_sales AS (\n    SELECT \n        DATE_TRUNC('month', soh.orderdate) AS sales_month,\n        EXTRACT(YEAR FROM soh.orderdate) AS sales_year,\n        EXTRACT(MONTH FROM soh.orderdate) AS sales_month_num,\n        SUM(soh.totaldue) AS total_revenue,\n        COUNT(DISTINCT soh.salesorderid) AS total_orders,\n        AVG(soh.totaldue) AS avg_order_value\n    FROM sales.salesorderheader soh\n    WHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\n    GROUP BY \n        DATE_TRUNC('month', soh.orderdate),\n        EXTRACT(YEAR FROM soh.orderdate),\n        EXTRACT(MONTH FROM soh.orderdate)\n)\nSELECT \n    sales_month,\n    sales_year,\n    sales_month_num,\n    total_revenue,\n    total_orders,\n    ROUND(avg_order_value, 2) AS avg_order_value,\n    LAG(total_revenue, 12) OVER (ORDER BY sales_month) AS previous_year_revenue,\n    LAG(total_orders, 12) OVER (ORDER BY sales_month) AS previous_year_orders,\n    ROUND(\n        ((total_revenue - LAG(total_revenue, 12) OVER (ORDER BY sales_month)) / \n        NULLIF(LAG(total_revenue, 12) OVER (ORDER BY sales_month), 0)) * 100, \n        2\n    ) AS yoy_revenue_growth_pct,\n    ROUND(\n        ((total_orders - LAG(total_orders, 12) OVER (ORDER BY sales_month)) / \n        NULLIF(LAG(total_orders, 12) OVER (ORDER BY sales_month), 0)) * 100, \n        2\n    ) AS yoy_orders_growth_pct\nFROM monthly_sales\nORDER BY sales_month\nLIMIT 1000\n---\nSELECT \n    DATE_TRUNC('month', soh.orderdate) AS sales_month,\n    st.name AS territory_name,\n    SUM(soh.totaldue) AS total_revenue,\n    COUNT(DISTINCT soh.salesorderid) AS total_orders,\n    LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.name ORDER BY DATE_TRUNC('month', soh.orderdate)) AS previous_year_revenue,\n    ROUND(\n        ((SUM(soh.totaldue) - LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.name ORDER BY DATE_TRUNC('month', soh.orderdate))) / \n        NULLIF(LAG(SUM(soh.totaldue), 12) OVER (PARTITION BY st.name ORDER BY DATE_TRUNC('month', soh.orderdate)), 0)) * 100, \n        2\n    ) AS yoy_growth_pct\nFROM sales.salesorderheader soh\nINNER JOIN sales.salesterritory st ON soh.territoryid = st.territoryid\nWHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\nGROUP BY DATE_TRUNC('month', soh.orderdate), st.name\nORDER BY sales_month, territory_name\nLIMIT 1000\n---\nSELECT \n    DATE_TRUNC('month', soh.orderdate) AS sales_month,\n    pc.name AS product_category,\n    SUM(sod.linetotal) AS total_revenue,\n    COUNT(DISTINCT soh.salesorderid) AS total_orders,\n    LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY pc.name ORDER BY DATE_TRUNC('month', soh.orderdate)) AS previous_year_revenue,\n    ROUND(\n        ((SUM(sod.linetotal) - LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY pc.name ORDER BY DATE_TRUNC('month', soh.orderdate))) / \n        NULLIF(LAG(SUM(sod.linetotal), 12) OVER (PARTITION BY pc.name ORDER BY DATE_TRUNC('month', soh.orderdate)), 0)) * 100, \n        2\n    ) AS yoy_growth_pct\nFROM sales.salesorderheader soh\nINNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid\nINNER JOIN production.product p ON sod.productid = p.productid\nINNER JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid\nINNER JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid\nWHERE soh.orderdate >= CURRENT_DATE - INTERVAL '3 years'\nGROUP BY DATE_TRUNC('month', soh.orderdate), pc.name\nORDER BY sales_month, total_revenue DESC\nLIMIT 1000	[]	{"data": {"labels": [], "datasets": [{"data": [], "label": "Ventas Actual", "backgroundColor": ["#4f46e5"]}, {"data": [], "label": "Ventas Anterior", "backgroundColor": ["#06b6d4"]}]}, "type": "bar", "title": "Ventas por Mes de los Últimos 3 Años", "columns": [{"key": "mes", "type": "string", "label": "Mes"}, {"key": "ventasActual", "type": "number", "label": "Ventas Actual"}, {"key": "ventasAnterior", "type": "number", "label": "Ventas Anterior"}], "options": {"scales": {"y": {"beginAtZero": true}}}, "description": "Este gráfico muestra las ventas mensuales para los últimos 3 años, comparadas con el año anterior."}	0	54	\N	2026-04-15 02:56:47.812
