12	97	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_sales AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, EXTRACT(YEAR FROM soh.orderdate) AS sales_year, EXTRACT(MONTH FROM soh.orderdate) AS sales_month_num, SUM(soh.totaldue) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, AVG(soh.totaldue) AS avg_order_value FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate), EXTRACT(YEAR FROM soh.orderdate), EXTRACT(MONTH FROM soh.orderdate) ) SELECT sales_month, sales_year, sales_month_num, total_revenue, total_orders, ROUND(avg_order_value, 2) AS avg_order_value, LAG(total_revenue, 12) OVER (ORDER BY sales_month) AS previous_year_revenue, LAG(total_orders, 12) OVER (ORDER BY sales_month) AS previous_year_orders, ROUND( ((total_revenue - LAG(total_revenue, 12) OVER (ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 12) OVER (ORDER BY sales_month), 0)) * 100, 2 ) AS yoy_revenue_growth_pct, ROUND( ((total_orders - LAG(total_orders, 12) OVER (ORDER BY sales_month)) / NULLIF(LAG(total_orders, 12) OVER (ORDER BY sales_month), 0)) * 100, 2 ) AS yoy_orders_growth_pct FROM monthly_sales ORDER BY sales_month LIMIT 1000	[{"sales_year": "2011", "sales_month": "2011-06-01T00:00:00.000Z", "total_orders": "5", "total_revenue": "16588.4568", "avg_order_value": "3317.69", "sales_month_num": "6", "previous_year_orders": null, "previous_year_revenue": null, "yoy_orders_growth_pct": null, "yoy_revenue_growth_pct": null}, {"sales_year": "2011", "sales_month": "2011-07-01T00:00:00.000Z", "total_orders": "231", "total_revenue": "2292182.8642", "avg_order_value": "9922.87", "sales_month_num": "7", "previous_year_orders": null, "previous_year_revenue": null, "yoy_orders_growth_pct": null, "yoy_revenue_growth_pct": null}, {"sales_year": "2011", "sales_mont