13	99	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 months' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), sales_base AS ( SELECT soh.salesorderid, soh.orderdate, soh.totaldue, soh.territoryid, soh.customerid, sod.productid, sod.linetotal, sod.orderqty FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date ), product_categories AS ( SELECT p.productid, pc.name AS product_category, ps.name AS product_subcategory FROM production.product p LEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid LEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid ), territory_info AS ( SELECT st.territoryid, st.name AS territory_name, st.group AS territory_group, cr.name AS country_region FROM sales.salesterritory st LEFT JOIN person.countryregion cr ON st.countryregioncode = cr.countryregioncode ) SELECT DATE_TRUNC('month', sb.orderdate) AS sales_month, EXTRACT(MONTH FROM sb.orderdate) AS sales_month_num, EXTRACT(YEAR FROM sb.orderdate) AS sales_year, pc.product_category, pc.product_subcategory, ti.territory_name, ti.territory_group, ti.country_region, COUNT(DISTINCT sb.salesorderid) AS total_orders, SUM(sb.orderqty) AS total_quantity, SUM(sb.linetotal) AS total_revenue, ROUND(AVG(sb.linetotal), 2) AS avg_line_total, ROUND(SUM(sb.linetotal) / NULLIF(COUNT(DISTINCT sb.salesorderid), 0), 2) AS avg_order_value FROM sales_base sb INNER JOIN product_categories pc ON sb.productid = pc.productid LEFT JOIN territory_info ti ON sb.territoryid = ti.territoryid GROUP BY DATE_TRUNC('month', sb.orderdate), EXTRACT(MONTH FROM sb.orderdate), EXTRACT(YEAR FROM sb.orderdate), pc.product_category, pc.product_subcategory, ti.territory_name, ti.territory_group, ti.country_region ORDER BY sales_month DESC, total_revenue DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 months' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_sales AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, SUM(soh.totaldue) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, ROUND(AVG(soh.totaldue), 2) AS avg_order_value FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate) ) SELECT sales_month, total_revenue, total_orders, avg_order_value, LAG(total_revenue, 1) OVER (ORDER BY sales_month) AS previous_month_revenue, ROUND(((total_revenue - LAG(total_revenue, 1) OVER (ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 1) OVER (ORDER BY sales_month), 0)) * 100, 2) AS mom_growth_pct FROM monthly_sales ORDER BY sales_month DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 months' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), sales_by_category AS ( SELECT pc.name AS product_category, ps.name AS product_subcategory, COUNT(DISTINCT soh.salesorderid) AS total_orders, SUM(sod.linetotal) AS total_revenue, SUM(sod.orderqty) AS total_quantity FROM sales.salesorderheader soh CROSS JOIN date_params dp INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid LEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid LEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY pc.name, ps.name ) SELECT product_category, product_subcategory, total_orders, total_quantity, total_revenue, ROUND((total_revenue / SUM(total_revenue) OVER ()) * 100, 2) AS revenue_share_pct, ROUND(total_revenue / NULLIF(total_quantity, 0), 2) AS avg_unit_price FROM sales_by_category ORDER BY total_revenue DESC LI