17	108	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), territory_sales AS ( SELECT st.territoryid, st.name AS territory_name, st.countryregioncode, st.group AS territory_group, COUNT(DISTINCT soh.salesorderid) AS total_orders, SUM(soh.totaldue) AS total_revenue, AVG(soh.totaldue) AS avg_order_value FROM sales.salesorderheader soh INNER JOIN sales.salesterritory st ON soh.territoryid = st.territoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY st.territoryid, st.name, st.countryregioncode, st.group ), territory_percentages AS ( SELECT territoryid, territory_name, countryregioncode, territory_group, total_orders, total_revenue, avg_order_value, ROUND((total_revenue / SUM(total_revenue) OVER ()) * 100, 2) AS revenue_percentage, ROUND((total_orders / SUM(total_orders) OVER ()) * 100, 2) AS order_percentage FROM territory_sales ) SELECT territory_name, territory_group, countryregioncode, total_orders, total_revenue, avg_order_value, revenue_percentage, order_percentage, CASE WHEN revenue_percentage < 10 THEN 'High Attention Needed' WHEN revenue_percentage < 15 THEN 'Moderate Attention' ELSE 'Normal Performance' END AS attention_level FROM territory_percentages ORDER BY revenue_percentage ASC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_territory_sales AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, st.territoryid, st.name AS territory_name, st.group AS territory_group, SUM(soh.totaldue) AS monthly_revenue FROM sales.salesorderheader soh INNER JOIN sales.salesterritory st ON soh.territoryid = st.territoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate), st.territoryid, st.name, st.group ), territory_trends AS ( SELECT territoryid, territory_name, territory_group, AVG(monthly_revenue) AS avg_monthly_revenue, MIN(monthly_revenue) AS min_monthly_revenue, MAX(monthly_revenue) AS max_monthly_revenue, STDDEV(monthly_revenue) AS revenue_volatility FROM monthly_territory_sales GROUP BY territoryid, territory_name, territory_group ) SELECT territory_name, territory_group, ROUND(avg_monthly_revenue, 2) AS avg_monthly_revenue, ROUND(min_monthly_revenue, 2) AS min_monthly_revenue, ROUND(max_monthly_revenue, 2) AS max_monthly_revenue, ROUND(revenue_volatility, 2) AS revenue_volatility, ROUND((avg_monthly_revenue / SUM(avg_monthly_revenue) OVER ()) * 100, 2) AS avg_revenue_percentage, CASE WHEN avg_monthly_revenue < (SELECT AVG(avg_monthly_revenue) * 0.7 FROM territory_trends) THEN 'Underperforming' ELSE 'Acceptable' END AS performance_status FROM territory_trends ORDER BY avg_monthly_revenue ASC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '1 year' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), current_year_sales AS ( SELECT st.territoryid, st.name AS territory_name, st.salesytd AS territory_sales_ytd, SUM(soh.totaldue) AS actual_sales_ytd FROM sales.salesorderheader soh INNER JOIN sales.salesterritory st ON soh.territoryid = st.territoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY st.territoryid, st.name, st.salesytd ), previous_year_sales AS ( SELECT st.territoryid, st.name AS territory_name, st.saleslastyear AS territory_sales_last_year FROM sales.salesterritory st ) SELECT cy.territory_name, cy.territory_sales_ytd, cy.actual_sales_ytd, py.territory_sales_last_year, ROUND(((cy.actual_sales_ytd - py.territory_sales_last_year) / NULLIF(py.territory_sales_last_year, 0)) * 100, 2) AS yoy_growth_pct, ROUND((cy.actual_sales_ytd / SUM(cy.actual_sales_ytd) OVER ()) * 100, 2) AS current_share_pct, CASE WHEN ((cy.actual_sales_ytd - py.territory_sales_last_year) / NULLIF(py.territory_