18	110	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), quarterly_revenue AS ( SELECT EXTRACT(YEAR FROM soh.orderdate) AS sales_year, EXTRACT(QUARTER FROM soh.orderdate) AS sales_quarter, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND EXTRACT(QUARTER FROM soh.orderdate) IN (3, 4) GROUP BY EXTRACT(YEAR FROM soh.orderdate), EXTRACT(QUARTER FROM soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT sales_year, CASE WHEN sales_quarter = 3 THEN 'Q3' ELSE 'Q4' END AS sales_period, total_revenue, total_orders, LAG(total_revenue) OVER (PARTITION BY sales_year ORDER BY sales_quarter) AS previous_quarter_revenue, ROUND(((total_revenue - LAG(total_revenue) OVER (PARTITION BY sales_year ORDER BY sales_quarter)) / NULLIF(LAG(total_revenue) OVER (PARTITION BY sales_year ORDER BY sales_quarter), 0)) * 100, 2) AS qoq_growth_pct FROM quarterly_revenue WHERE sales_quarter IN (3, 4) ORDER BY sales_year, sales_quarter LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), q3_q4_comparison AS ( SELECT EXTRACT(YEAR FROM soh.orderdate) AS sales_year, EXTRACT(QUARTER FROM soh.orderdate) AS sales_quarter, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COUNT(DISTINCT soh.customerid) AS unique_customers FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND EXTRACT(QUARTER FROM soh.orderdate) IN (3, 4) GROUP BY EXTRACT(YEAR FROM soh.orderdate), EXTRACT(QUARTER FROM soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT MAX(CASE WHEN sales_quarter = 3 THEN sales_year END) AS comparison_year, MAX(CASE WHEN sales_quarter = 3 THEN total_revenue END) AS q3_revenue, MAX(CASE WHEN sales_quarter = 4 THEN total_revenue END) AS q4_revenue, MAX(CASE WHEN sales_quarter = 3 THEN total_orders END) AS q3_orders, MAX(CASE WHEN sales_quarter = 4 THEN total_orders END) AS q4_orders, MAX(CASE WHEN sales_quarter = 3 THEN unique_customers END) AS q3_customers, MAX(CASE WHEN sales_quarter = 4 THEN unique_customers END) AS q4_customers, ROUND(((MAX(CASE WHEN sales_quarter = 4 THEN total_revenue END) - MAX(CASE WHEN sales_quarter = 3 THEN total_revenue END)) / NULLIF(MAX(CASE WHEN sales_quarter = 3 THEN total_revenue END), 0)) * 100, 2) AS q3_vs_q4_growth_pct FROM q3_q4_comparison GROUP BY sales_year ORDER BY comparison_year LIMIT 1000	[{"sales_year": "2011", "sales_period": "Q3", "total_orders": "638", "total_revenue": "5647550.6249", "qoq_growth_pct": null, "previous_quarter_revenue": null}, {"sales_year": "2011", "sales_period": "Q4", "total_orders": "785", "total_revenue": "7434031.3872", "qoq_growth_pct": "31.63", "previous_quarter_revenue": "5647550.6249"}, {"sales_year": "2012", "sales_period": "Q3", "total_orders": "1022", "total_revenue": "10164406.8647", "qoq_growth_pct": null, "previous_quarter_revenue": null}, {"sales_year": "2012", "sales_period": "Q4", "total_orders": "1082", "total_revenue": "8132061.5543", "qoq_growth_pct": "-19.99", "previous_quarter_revenue": "10164406.8647"}, {"sales_year": "2013", "sales_period": "Q3", "total_orders": "5320", "total_revenue": "14339319.1989", "qoq_growth_pct": null, "previous_quarter_revenue": null}, {"sales_year": "2013", "sales_period": "Q4", "total_orders": "6121", "total_revenue": "13629621.0978", "qoq_growth_pct": "-4.95", "previous_quarter_revenue": "14339319.1989"}, {"q3_orders": "638", "q4_orders": "785", "q3_revenue": "5647550.6249", "q4_revenue": "7434031.3872", "q3_customers": "638", "q4_customers": "785", "comparison_year": "2011", "q3_vs_q4_growth_pct": "31.63"}, {"q3_orders": "1022", "q4_orders": "1082", "