19	113	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), customer_orders AS ( SELECT c.customerid, DATE_TRUNC('month', soh.orderdate) AS order_month FROM sales.salesorderheader soh INNER JOIN sales.customer c ON soh.customerid = c.customerid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND soh.totaldue > 0 GROUP BY c.customerid, DATE_TRUNC('month', soh.orderdate) ), customer_retention AS ( SELECT curr.order_month AS current_month, COUNT(DISTINCT curr.customerid) AS total_customers_current, COUNT(DISTINCT prev.customerid) AS returning_customers, ROUND( (COUNT(DISTINCT prev.customerid) * 100.0 / NULLIF(COUNT(DISTINCT curr.customerid), 0)), 2 ) AS retention_rate_pct FROM customer_orders curr LEFT JOIN customer_orders prev ON curr.customerid = prev.customerid AND prev.order_month = curr.order_month - INTERVAL '1 month' GROUP BY curr.order_month ) SELECT current_month AS sales_month, total_customers_current, COALESCE(returning_customers, 0) AS returning_customers, COALESCE(retention_rate_pct, 0) AS retention_rate_pct FROM customer_retention ORDER BY current_month LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), customer_cohorts AS ( SELECT c.customerid, DATE_TRUNC('month', MIN(soh.orderdate)) AS cohort_month FROM sales.salesorderheader soh INNER JOIN sales.customer c ON soh.customerid = c.customerid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND soh.totaldue > 0 GROUP BY c.customerid ), customer_activity AS ( SELECT cc.cohort_month, DATE_TRUNC('month', soh.orderdate) AS activity_month, COUNT(DISTINCT c.customerid) AS active_customers FROM sales.salesorderheader soh INNER JOIN sales.customer c ON soh.customerid = c.customerid INNER JOIN customer_cohorts cc ON c.customerid = cc.customerid C