22	120	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), product_revenue AS ( SELECT p.productid, p.name AS product_name, ps.name AS product_subcategory, pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COALESCE(SUM(sod.orderqty), 0) AS total_quantity FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid LEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid LEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY p.productid, p.name, ps.name, pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT product_name, product_category, product_subcategory, total_revenue, total_orders, total_quantity, ROUND(total_revenue / NULLIF(total_orders, 0), 2) AS avg_order_value FROM product_revenue ORDER BY total_revenue DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), category_revenue AS ( SELECT pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COUNT(DISTINCT p.productid) AS unique_products, COALESCE(SUM(sod.orderqty), 0) AS total_quantity FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid LEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid LEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT product_category, total_revenue, total_orders, unique_products, total_quantity, ROUND(total_revenue / NULLIF(total_orders, 0), 2) AS avg_order_value, ROUND((total_revenue / SUM(total_revenue) OVER ()) * 100, 2) AS revenue_share_pct FROM category_revenue ORDER BY total_revenue DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_product_revenue AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid LEFT JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid LEFT JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate), pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT sales_month, product_category, total_revenue, total_orders, LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month) AS previous_month_revenue, ROUND(((total_revenue - LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month), 0)) * 100, 2) AS mom_growth_pct FROM monthly_product_revenue ORDER BY sales_month DESC, total_revenue DESC LIMIT 1000	[{"product_name": "Mountain-200 Black, 38", "total_orders": "1252", "total_revenue": "4400592.7511", "total_quantity": "2977", "avg_order_value": "3514.85", "product_category": "Bikes", "product_subcategory": "Mount