31	174	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_revenue AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND soh.totaldue > 0 AND soh.totaldue IS NOT NULL GROUP BY DATE_TRUNC('month', soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT sales_month, total_revenue, total_orders, LAG(total_revenue, 1) OVER (ORDER BY sales_month) AS previous_month_revenue, LAG(total_revenue, 12) OVER (ORDER BY sales_month) AS previous_year_revenue, ROUND(((total_revenue - LAG(total_revenue, 1) OVER (ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 1) OVER (ORDER BY sales_month), 0)) * 100, 2) AS mom_growth_pct, ROUND(((total_revenue - LAG(total_revenue, 12) OVER (ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 12) OVER (ORDER BY sales_month), 0)) * 100, 2) AS yoy_growth_pct, SUM(total_revenue) OVER (ORDER BY sales_month ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue FROM monthly_revenue ORDER BY sales_month LIMIT 1000	[{"sales_month": "2011-06-01T00:00:00.000Z", "total_orders": "5", "total_revenue": "16588.4568", "mom_growth_pct": null, "yoy_growth_pct": null, "cumulative_revenue": "16588.4568", "previous_year_revenue": null, "previous_month_revenue": null}, {"sales_month": "2011-07-01T00:00:00.000Z", "total_orders": "231", "total_revenue": "2292182.8642", "mom_growth_pct": "13717.94", "yoy_growth_pct": null, "cumulative_revenue": "2308771.3210", "previous_year_revenue": null, "previous_month_revenue": "16588.4568"}, {"sales_month": "2011-08-01T00:00:00.000Z", "total_orders": "250", "total_revenue": "2800576.1637", "mom_growth_pct": "22.18", "yoy_growth_pct": null, "cumulative_revenue": "5109347.4847", "previ