23	123	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), quarterly_revenue AS ( SELECT EXTRACT(QUARTER FROM soh.orderdate) AS sales_quarter, EXTRACT(YEAR FROM soh.orderdate) AS sales_year, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND EXTRACT(QUARTER FROM soh.orderdate) IN (3, 4) GROUP BY EXTRACT(QUARTER FROM soh.orderdate), EXTRACT(YEAR FROM soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT sales_quarter, sales_year, total_revenue, total_orders, ROUND(total_revenue / NULLIF(total_orders, 0), 2) AS avg_order_value FROM quarterly_revenue WHERE sales_quarter IN (3, 4) ORDER BY sales_year, sales_quarter LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), q3_q4_comparison AS ( SELECT EXTRACT(YEAR FROM soh.orderdate) AS sales_year, COALESCE(SUM(CASE WHEN EXTRACT(QUARTER FROM soh.orderdate) = 3 THEN soh.totaldue ELSE 0 END), 0) AS q3_revenue, COALESCE(SUM(CASE WHEN EXTRACT(QUARTER FROM soh.orderdate) = 4 THEN soh.totaldue ELSE 0 END), 0) AS q4_revenue, COUNT(DISTINCT CASE WHEN EXTRACT(QUARTER FROM soh.orderdate) = 3 THEN soh.salesorderid END) AS q3_orders, COUNT(DISTINCT CASE WHEN EXTRACT(QUARTER FROM soh.orderdate) = 4 THEN soh.salesorderid END) AS q4_orders FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND EXTRACT(QUARTER FROM soh.orderdate) IN (3, 4) GROUP BY EXTRACT(YEAR FROM soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT sales_year, q3_revenue, q4_revenue, q4_revenue - q3_revenue AS revenue_difference, ROUND(((q4_revenue - q3_revenue) / NULLIF(q3_revenue, 0)) * 100, 2) AS q4_vs_q3_growth_pct, q3_orders, q4_orders FROM q3_q4_comparison WHERE q3_revenue > 0 OR q4_revenue > 0 ORDER BY sales_year LIMIT 1000	[{"sales_year": "2011", "total_orders": "638", "sales_quarter": "3", "total_revenue": "5647550.6249", "avg_order_value": "8851.96"}, {"sales_year": "2011", "total_orders": "785", "sales_quarter": "4", "total_revenue": "7434031.3872", "avg_order_value": "9470.10"}, {"sales_year": "2012", "total_orders": "1022", "sales_quarter": "3", "total_revenue": "10164406.8647", "avg_order_value": "9945.60"}, {"sales_year": "2012", "total_orders": "1082", "sales_quarter": "4", "total_revenue": "8132061.5543", "avg_order_value": "7515.77"}, {"sales_year": "2013", "total_orders": "5320", "sales_quarter": "3", "total_revenue": "14339319.1989", "avg_order_value": "2695.36"}, {"sales_year": "2013", "total_orders": "6121", "sales_quarter": "4", "total_revenue": "13629621.0978", "avg_order_value": "2226.70"}, {"q3_orders": "638", "q4_orders": "785", "q3_revenue": "5647550.6249", "q4_revenue": "7434031.3872", "sales_year": "2011", "revenue_difference": "1786480.7623", "q4_vs_q3_growth_pct": "31.63"}, {"q3_orders": "1022", "q4_orders": "1082", "q3_revenue": "10164406.8647", "q4_revenue": "8132061.5543", "sales_year": "2012", "revenue_difference": "-2032345.3104", "q4_vs_q3_growth_pct": "-19.99"}, {"q3_orders": "5320", "q4_orders": "6121", "q3_revenue": "14339319.1989", "q4_revenue": "13629621.0978", "sales_year": "2013", "revenue_difference": "-709698.1011", "q4_vs_q3_growth_pct": "-4.95"}]	{"fill": {"opacity": 1}, "grid": {"xaxis": {"lines": {"show": false}}, "yaxis": {"lines": {"show": true}}, "borderColor": "#E5E7EB", "strokeDashArray": 4}, "type": "line", "title": "Ingresos Q3 vs Q4 por Año", "xaxis": {"axisTicks": {"show": false}, "axisBorder": {"show": false}}, "yaxis": {"labels": {}}, "colors": ["#4f46e5", "#D1D5DB"], "legend": {"show": true, "position": "top"}, "series": [{"data": [], "name": "Q3 Ingresos", "dataKey": "q3_revenue"}, {"data": [], "name": "Q4 Ingresos", "d