24	126	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), cart_metrics AS ( SELECT DATE_TRUNC('month', sci.datecreated) AS sales_month, COUNT(DISTINCT sci.shoppingcartid) AS cart_sessions, COUNT(sci.shoppingcartitemid) AS cart_items FROM sales.shoppingcartitem sci CROSS JOIN date_params dp WHERE sci.datecreated >= dp.min_date AND sci.datecreated <= dp.max_date GROUP BY DATE_TRUNC('month', sci.datecreated) ), order_metrics AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, COUNT(DISTINCT soh.salesorderid) AS total_orders, COALESCE(SUM(soh.totaldue), 0) AS total_revenue FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate) ), funnel_stages AS ( SELECT COALESCE(cm.sales_month, om.sales_month) AS sales_month, COALESCE(cm.cart_sessions, 0) AS cart_sessions, COALESCE(cm.cart_items, 0) AS cart_items, COALESCE(om.total_orders, 0) AS total_orders, COALESCE(om.total_revenue, 0) AS total_revenue FROM cart_metrics cm FULL OUTER JOIN order_metrics om ON cm.sales_month = om.sales_month ) SELECT sales_month, cart_sessions, cart_items, total_orders, total_revenue, ROUND((total_orders::numeric / NULLIF(cart_sessions, 0)) * 100, 2) AS cart_to_order_conversion_pct, ROUND((total_orders::numeric / NULLIF(cart_items, 0)) * 100, 2) AS item_to_order_conversion_pct, ROUND((total_revenue::numeric / NULLIF(cart_sessions, 0)), 2) AS revenue_per_cart_session FROM funnel_stages WHERE cart_sessions > 0 ORDER BY sales_month LIMIT 1000	[{"cart_items": "3", "sales_month": "2013-11-01T00:00:00.000Z", "total_orders": "2103", "cart_sessions": "2", "total_revenue": "3694668.0127", "revenue_per_cart_session": "1847334.01", "cart_to_order_conversion_pct": "105150.00", "item_to_order_conversion_pct": "70100.00"}]	{"fill": {"opacity": 1}, "grid": {"xaxis": {"lines": {"show": true}}, "yaxis": {"line