28	167	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), quarterly_revenue AS ( SELECT EXTRACT(YEAR FROM soh.orderdate) AS sales_year, EXTRACT(QUARTER FROM soh.orderdate) AS sales_quarter, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND soh.totaldue > 0 GROUP BY EXTRACT(YEAR FROM soh.orderdate), EXTRACT(QUARTER FROM soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ), q3_q4_comparison AS ( SELECT sales_year, MAX(CASE WHEN sales_quarter = 3 THEN total_revenue END) AS q3_revenue, MAX(CASE WHEN sales_quarter = 3 THEN total_orders END) AS q3_orders, MAX(CASE WHEN sales_quarter = 4 THEN total_revenue END) AS q4_revenue, MAX(CASE WHEN sales_quarter = 4 THEN total_orders END) AS q4_orders FROM quarterly_revenue WHERE sales_quarter IN (3, 4) GROUP BY sales_year ) SELECT sales_year, q3_revenue, q4_revenue, q3_orders, q4_orders, ROUND(((q4_revenue - q3_revenue) / NULLIF(q3_revenue, 0)) * 100, 2) AS q3_vs_q4_growth_pct, CASE WHEN q4_revenue > q3_revenue THEN 'Q4 Superior' WHEN q4_revenue < q3_revenue THEN 'Q3 Superior' ELSE 'Equal' END AS quarter_comparison FROM q3_q4_comparison WHERE q3_revenue > 0 AND q4_revenue > 0 ORDER BY sales_year LIMIT 1000	[{"q3_orders": "638", "q4_orders": "785", "q3_revenue": "5647550.6249", "q4_revenue": "7434031.3872", "sales_year": "2011", "quarter_comparison": "Q4 Superior", "q3_vs_q4_growth_pct": "31.63"}, {"q3_orders": "1022", "q4_orders": "1082", "q3_revenue": "10164406.8647", "q4_revenue": "8132061.5543", "sales_year": "2012", "quarter_comparison": "Q3 Superior", "q3_vs_q4_growth_pct": "-19.99"}, {"q3_orders": "5320", "q4_orders": "6121", "q3_revenue": "14339319.1989", "q4_revenue": "13629621.0978", "sales_year": "2013", "quarter_comparison": "Q3 Superior", "q3_vs_q4_growth