30	172	WITH date_params AS ( SELECT DATE_TRUNC('month', MAX(orderdate)) - INTERVAL '11 months' AS min_date, DATE_TRUNC('month', MAX(orderdate)) AS max_date FROM sales.salesorderheader ), monthly_sales AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, COALESCE(SUM(soh.totaldue), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COALESCE(AVG(soh.totaldue), 0) AS avg_order_value FROM sales.salesorderheader soh CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date AND soh.totaldue > 0 AND soh.totaldue IS NOT NULL GROUP BY DATE_TRUNC('month', soh.orderdate) HAVING COALESCE(SUM(soh.totaldue), 0) > 0 ) SELECT sales_month, total_revenue, total_orders, avg_order_value FROM monthly_sales ORDER BY sales_month LIMIT 1000	[{"sales_month": "2013-07-01T00:00:00.000Z", "total_orders": "1740", "total_revenue": "5521840.8430", "avg_order_value": "3173.4717488505747126"}, {"sales_month": "2013-08-01T00:00:00.000Z", "total_orders": "1789", "total_revenue": "3733973.0149", "avg_order_value": "2087.1844689211850196"}, {"sales_month": "2013-09-01T00:00:00.000Z", "total_orders": "1791", "total_revenue": "5083505.3410", "avg_order_value": "2838.3614410943606924"}, {"sales_month": "2013-10-01T00:00:00.000Z", "total_orders": "1968", "total_revenue": "5374375.9724", "avg_order_value": "2730.8820997967479675"}, {"sales_month": "2013-11-01T00:00:00.000Z", "total_orders": "2103", "total_revenue": "3694668.0127", "avg_order_value": "1756.8559261531145982"}, {"sales_month": "2013-12-01T00:00:00.000Z", "total_orders": "2050", "total_revenue": "4560577.1127", "avg_order_value": "2224.6717622926829268"}, {"sales_month": "2014-01-01T00:00:00.000Z", "total_orders": "2141", "total_revenue": "4798027.8851", "avg_order_value": "2241.0218986921999066"}, {"sales_month": "2014-02-01T00:00:00.000Z", "total_orders": "1756", "total_revenue": "1478213.2971", "avg_order_value": "841.8071167995444191"}, {"sales_month": "2014-03-01T00:00:00.00