32	177	WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), sales_by_category AS ( SELECT pc.productcategoryid, pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COALESCE(AVG(sod.linetotal), 0) AS avg_line_value, COALESCE(SUM(sod.orderqty), 0) AS total_quantity FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid INNER JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid INNER JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY pc.productcategoryid, pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT product_category, total_revenue, total_orders, avg_line_value, total_quantity, ROUND((total_revenue / SUM(total_revenue) OVER ()) * 100, 2) AS revenue_share_pct, RANK() OVER (ORDER BY total_revenue DESC) AS revenue_rank FROM sales_by_category ORDER BY total_revenue DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), monthly_category_sales AS ( SELECT DATE_TRUNC('month', soh.orderdate) AS sales_month, pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid INNER JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid INNER JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY DATE_TRUNC('month', soh.orderdate), pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT sales_month, product_category, total_revenue, total_orders, LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month) AS previous_month_revenue, ROUND(((total_revenue - LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month)) / NULLIF(LAG(total_revenue, 1) OVER (PARTITION BY product_category ORDER BY sales_month), 0)) * 100, 2) AS mom_growth_pct FROM monthly_category_sales ORDER BY sales_month, total_revenue DESC LIMIT 1000 --- WITH date_params AS ( SELECT MAX(orderdate) - INTERVAL '3 years' AS min_date, MAX(orderdate) AS max_date FROM sales.salesorderheader ), category_performance AS ( SELECT pc.name AS product_category, COALESCE(SUM(sod.linetotal), 0) AS total_revenue, COUNT(DISTINCT soh.salesorderid) AS total_orders, COALESCE(SUM(sod.orderqty), 0) AS total_units, COUNT(DISTINCT p.productid) AS unique_products, COUNT(DISTINCT soh.customerid) AS unique_customers FROM sales.salesorderheader soh INNER JOIN sales.salesorderdetail sod ON soh.salesorderid = sod.salesorderid INNER JOIN production.product p ON sod.productid = p.productid INNER JOIN production.productsubcategory ps ON p.productsubcategoryid = ps.productsubcategoryid INNER JOIN production.productcategory pc ON ps.productcategoryid = pc.productcategoryid CROSS JOIN date_params dp WHERE soh.orderdate >= dp.min_date AND soh.orderdate <= dp.max_date GROUP BY pc.name HAVING COALESCE(SUM(sod.linetotal), 0) > 0 ) SELECT product_category, total_revenue, total_orders, total_units, unique_products, unique_customers, ROUND(total_revenue / NULLIF(total_orders, 0), 2) AS avg_order_value, ROUND(total_revenue / NULLIF(total_units, 0), 2) AS avg_unit_price, ROUND(total_revenue / NULLIF(unique_customers, 0), 2) AS revenue_per_customer FROM category_performance ORDER BY total_revenue DESC LIMIT 1000	[{"revenue_rank": "1", "tot